1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a create-owner request whose city already holds the maximum number of owners
11	 * ({@value #CAPACITY}), responding 409 via {@link CityAtCapacityException}. Cities are
12	 * compared exactly.
13	 */
14	public class RequireCityCapacity {
15	
16	    /** Maximum owners allowed per city; the request is rejected once this is reached. */
17	    static final int CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        long inCity = ownerRepository.findAll().stream()
23	            .map(Owner::getCity)
24	            .filter(existing -> existing != null && existing.equals(city))
25	            .count();
26	        if (inCity >= CAPACITY) {
27	            throw new CityAtCapacityException(city, CAPACITY);
28	        }
29	    }
30	}
