3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Shared counting over the owners already registered on a given (adjusted, business-day)
10	 * {@link Owner#getRegistrationDate() registrationDate}. Both the per-day capacity limit and
11	 * the bulk-signup warning bucket owners by the same day, so they share this count.
12	 */
13	final class OwnerRegistrations {
14	
15	    private OwnerRegistrations() {
16	    }
17	
18	    /** The number of stored owners whose registrationDate equals {@code date}. */
19	    static long countOn(OwnerRepository ownerRepository, LocalDate date) {
20	        return ownerRepository.findAll().stream()
21	            .map(Owner::getRegistrationDate)
22	            .filter(date::equals)
23	            .count();
24	    }
25	}
